import { useRef, useState } from "react";
import { FiSearch, FiXCircle } from "react-icons/fi";
import { getWalletErrorMessage } from "../utils/walletErrors";

export default function PendingWalletRecovery({ cont, initialHash = "" }) {
    const [hash, setHash] = useState(initialHash);
    const [info, setInfo] = useState(null);
    const [busy, setBusy] = useState(false);
    const [message, setMessage] = useState("");
    const [replacementHash, setReplacementHash] = useState("");
    const active = useRef(false);
    if (typeof cont?.inspect_pending_wallet_transaction !== "function") return null;
    const run = async cancel => {
        if (active.current) return;
        if (cancel && !window.confirm(`${info.retryRequired ? "前のキャンセル要求の結果が未確定のため、同じnonceだけで手数料を更新して再試行します。問題作成は再送しません。\n" : ""}nonce ${info.nonce} の保留取引を取り消すため、自分宛てに0 POLの取引を同じnonceで要求します。TFTは送金しませんが、手数料がかかります。MetaMaskで手数料とnonceを確認して承認してください。元の取引が先に確定している場合は取り消せません。`)) return;
        active.current = true; setBusy(true); setMessage("");
        try {
            if (cancel) {
                const result = await cont.cancel_pending_wallet_transaction(hash.trim(), { retry: Boolean(info.retryRequired) });
                setReplacementHash(result.hash);
                setMessage("同じnonceのキャンセル要求を送信しました。まだ取り消し完了ではありません。下の取引リンクで確定を確認し、元の問題が作成されていないか一覧も確認してください。");
                setInfo(null);
            } else {
                const result = await cont.inspect_pending_wallet_transaction(hash.trim());
                setInfo(result);
                setReplacementHash(result.previousHash || "");
                setMessage(result.status === "confirmed" ? "この取引は確定済みです。問題一覧と元の取引を確認してください。自己宛てキャンセルの場合、問題作成の成功を意味しません。"
                    : result.status === "reverted" ? "この取引は失敗として確定しました。問題一覧と元の取引の状態を確認してください。"
                        : result.status === "nonce_consumed" ? "このnonceはすでに別の取引で処理されています。元の作成取引・キャンセル取引の履歴を確認してください。"
                            : result.status === "queued" ? `この取引より先にnonce ${result.blockingNonce} の処理が必要です。古い取引から確認してください。`
                                : "チェーン上で保留中です。手数料を再計算しました。キャンセルは自動送信しません。");
            }
        } catch (error) {
            setInfo(null);
            if (error.transactionHash) setReplacementHash(error.transactionHash);
            setMessage(getWalletErrorMessage(error) || "取引の状態を確認できませんでした。ハッシュ・接続アカウント・通信状態を確認してください。取引は自動再送しません。");
        } finally { active.current = false; setBusy(false); }
    };
    return <section aria-label="保留取引の復旧" style={{ marginTop: 16, padding: "12px 0", color: "var(--text-primary, #f1f5f9)", overflowWrap: "anywhere" }}>
        <h4 className="heading-md">保留取引の復旧</h4>
        <label style={{ display: "block" }}>取引ハッシュ
            <input aria-label="保留中の取引ハッシュ" value={hash} disabled={busy} onChange={event => { setHash(event.target.value); setInfo(null); setReplacementHash(""); }}
                placeholder="0x..." autoCapitalize="none" autoCorrect="off" spellCheck={false}
                style={{ width: "100%", minHeight: 44, margin: "8px 0", padding: 8, borderRadius: 6, border: "1px solid #64748b", background: "#171b28", color: "#f1f5f9" }} />
        </label>
        <button type="button" className="btn-ghost" style={{ minHeight: 44 }} disabled={busy || !hash.trim()} onClick={() => run(false)}><FiSearch aria-hidden="true" /> 保留取引を確認</button>
        {info?.status === "pending" && <>
            <dl style={{ marginTop: 12 }}>
                <dt>nonce</dt><dd>{info.nonce}</dd>
                <dt>元の手数料上限 / 現在の基本手数料</dt><dd>{info.originalMaxFeeGwei} / {info.baseFeeGwei} Gwei</dd>
                <dt>キャンセルの上限 / 優先手数料</dt><dd>{info.maxFeeGwei} / {info.priorityFeeGwei} Gwei</dd>
                <dt>キャンセルの最大手数料</dt><dd>{info.maximumCostPOL} POL</dd>
            </dl>
            {!info.enoughBalance && <p role="alert">手数料用のAmoy POLが不足しています。</p>}
            {info.retryRequired && <p role="status">前のキャンセル要求が未確定です。今回もnonce {info.nonce} の自己宛て0 POLだけを要求し、問題作成は再送しません。</p>}
            <button type="button" className="btn-ghost" style={{ minHeight: 44 }} disabled={busy || !info.enoughBalance} onClick={() => run(true)}>
                <FiXCircle aria-hidden="true" /> {info.cancellation ? "キャンセル取引の手数料を更新" : "保留取引のキャンセルを確認"}
            </button>
        </>}
        {busy && <p role="status">{info ? "MetaMaskの確認待ちです。" : "保留状態を確認しています。"}</p>}
        {message && <p role="status" style={{ marginTop: 12 }}>{message}</p>}
        {replacementHash && <p><a href={`https://amoy.polygonscan.com/tx/${replacementHash}`} target="_blank" rel="noopener noreferrer">キャンセル要求の取引を確認</a>
            <button type="button" className="btn-ghost" disabled={busy} onClick={() => { setHash(replacementHash); setInfo(null); setReplacementHash(""); }}>この取引を再確認</button></p>}
        <p><a href="https://support.metamask.com/manage-crypto/transactions/how-to-speed-up-or-cancel-a-pending-transaction" target="_blank" rel="noopener noreferrer">MetaMask公式の保留取引・キャンセル手順</a></p>
    </section>;
}
