import { useEffect, useRef, useState } from "react";
import { FiRefreshCw } from "react-icons/fi";
import { getWalletErrorMessage } from "../utils/walletErrors";

export default function NewQuizCreationRecovery({ cont, error, disabled, onReady, onBusyChange }) {
    const [busy, setBusy] = useState(false);
    const [message, setMessage] = useState("");
    const [confirmedHashes, setConfirmedHashes] = useState([]);
    const active = useRef(false);
    const panel = useRef(null);
    useEffect(() => {
        if (message) panel.current?.scrollIntoView?.({ block: "center", inline: "nearest", behavior: "auto" });
    }, [message]);
    if (typeof cont?.prepare_new_quiz_after_cancellation !== "function") return null;
    const prepare = async () => {
        if (active.current || disabled) return;
        if (!window.confirm("古い作成・承認の確認記録を退避し、新しい問題として再開します。未確定取引やRPCの不一致があっても続行します。前の取引が後から確定すると問題が重複する可能性があり、新しい取引も順番待ちになる場合があります。問題一覧とMetaMaskの履歴を確認してください。この操作では取引を送信せず、作成済みの問題や入力内容も削除しません。")) return;
        active.current = true; setBusy(true); onBusyChange?.(true); setMessage(""); setConfirmedHashes([]);
        try {
            const result = await cont.prepare_new_quiz_after_cancellation();
            setConfirmedHashes(result.confirmedHashes || []);
            onReady?.();
            setMessage(result.confirmedHashes?.length
                ? "作成済みの取引も見つかりました。下の履歴と問題一覧を確認し、同じ問題の重複投稿を避けてください。古い確認記録は退避しました。新しい問題は通常の作成ボタンから投稿できます。"
                : result.warnings?.length
                    ? "未確定取引またはRPCの確認できない結果がありますが、新規投稿を止めず、古い確認記録を退避しました。通常の作成ボタンから新しい問題として投稿できます。前の取引が確定すると重複したり、新しい取引が順番待ちになる場合があります。まだ取引は送信していません。"
                    : "保留なしを2つのRPCで確認し、古い作成・承認の確認記録を退避しました。入力内容は保持しています。通常の作成ボタンから新しい問題として投稿できます。まだ取引は送信していません。");
        } catch (failure) {
            setMessage(getWalletErrorMessage(failure) || "新規投稿の準備を完了できませんでした。古い記録を解除せず停止しました。通信状態を確認してください。");
        } finally { active.current = false; setBusy(false); onBusyChange?.(false); }
    };
    return <section ref={panel} aria-label="キャンセル後の新規投稿" style={{ margin: "16px 0", color: "var(--text-primary, #f1f5f9)", overflowWrap: "anywhere", scrollMarginBottom: 90 }}>
        <details open={Boolean(error)}>
            <summary>キャンセル後に新しい問題を投稿</summary>
            <button type="button" className="btn-ghost" style={{ minHeight: 44, marginTop: 12 }} disabled={busy || disabled} onClick={prepare}>
                <FiRefreshCw aria-hidden="true" /> 新しい問題として再開
            </button>
        </details>
        {busy && <p role="status">保留取引と接続アカウントを確認しています。取引は送信しません。</p>}
        {message && <p role="status">{message}</p>}
        {confirmedHashes.map(hash => <p key={hash}><a href={`https://amoy.polygonscan.com/tx/${hash}`} target="_blank" rel="noopener noreferrer">作成済みの取引を確認</a></p>)}
    </section>;
}
